# NAMES is a literal fixed before closure, staging and commit.
pub=str((Q/'publication.json').relative_to(R));c=rd(Q/'closure.json')
require(c['all_passed'] is True and bindings(c),'Closure failed or changed')
require(not git('diff','--cached','--name-only'),'Index not empty')
